(7234543, 1120292, 121111, '<td valign="top">Great conversion to b&amp;W, love the composition</td>', 'Great conversion to b&W, love the composition', '2014-06-30 01:16:41.000000', NULL, 1),
(7234544, 1120339, 121111, '<td valign="top">Gorgeous detail</td>', 'Gorgeous detail', '2014-06-30 01:17:22.000000', NULL, 1),
(7234545, 1120279, 121111, '<td valign="top">wow !!</td>', 'wow !!', '2014-06-30 01:17:59.000000', NULL, 1),
(7234546, 1120468, 121111, '<td valign="top">What a sky !</td>', 'What a sky !', '2014-06-30 01:19:10.000000', NULL, 1),
(7234547, 1120229, 121111, '<td valign="top">talk about dramatic</td>', 'talk about dramatic', '2014-06-30 01:19:31.000000', NULL, 1),
(7234551, 1119390, 68178, '<td valign="top">I know this place! Last time I went by the flood made it not so appealing. You found a nice vantage point or they are cleaning up well, either way very nice.</td>', 'I know this place! Last time I went by the flood made it not so appealing. You found a nice vantage point or they are cleaning up well, either way very nice.', '2014-06-30 01:35:52.000000', NULL, 1),
(7234552, 1120482, 18197, '<td valign="top">Cool tower, setting and mood. Looks like some sharpening artifacts around the tower. Not voting yet.</td>', 'Cool tower, setting and mood. Looks like some sharpening artifacts around the tower. Not voting yet.', '2014-06-30 01:35:56.000000', NULL, 1),
(7234553, 1120279, 18197, '<td valign="top">Very neat building. Ought to do well. Seems over sharpened to me. Not voting yet.</td>', 'Very neat building. Ought to do well. Seems over sharpened to me. Not voting yet.', '2014-06-30 01:36:46.000000', NULL, 1),
(7234555, 1119697, 18197, '<td valign="top">Absolutely splendid photo. I am a fan of natural HDR and this is pretty good. I might have backed off just a bit but I really love this. Not voting yet.</td>', 'Absolutely splendid photo. I am a fan of natural HDR and this is pretty good. I might have backed off just a bit but I really love this. Not voting yet.', '2014-06-30 01:38:35.000000', NULL, 1),
(7234557, 1120294, 18197, '<td valign="top">Your title confuses me but the photo is splendid. Not voting yet.</td>', 'Your title confuses me but the photo is splendid. Not voting yet.', '2014-06-30 01:39:24.000000', NULL, 1),
(7234561, 1120175, 18197, '<td valign="top">I am a fan of natural HDR. This is pretty good but you need to watch the halos and watch out for wonky sky. Not voting yet.</td>', 'I am a fan of natural HDR. This is pretty good but you need to watch the halos and watch out for wonky sky. Not voting yet.', '2014-06-30 01:41:18.000000', NULL, 1),
(7234563, 1120478, 18197, '<td valign="top">I love this and love that you kept the sun in the frame. It looks like you may have corrected for lens distortion  and maybe over corrected. Or I may be wrong. But in any event, well done here. Not voting yet.</td>', 'I love this and love that you kept the sun in the frame. It looks like you may have corrected for lens distortion  and maybe over corrected. Or I may be wrong. But in any event, well done here. Not voting yet.', '2014-06-30 01:42:59.000000', NULL, 1),
(7234566, 1120494, 18197, '<td valign="top">Wow. I love this! What an interesting building. Seems to be leaning to the left just a little, but otherwise, absolutely first rate subject, capture and presentation. Not voting yet.</td>', 'Wow. I love this! What an interesting building. Seems to be leaning to the left just a little, but otherwise, absolutely first rate subject, capture and presentation. Not voting yet.', '2014-06-30 01:44:50.000000', NULL, 1),
(7234572, 1119404, 68178, '<td valign="top">There is two of  you... One of my favorite buildings nearby. Looks like the flood has been cleaned up or you find a nice angle. Well done!</td>', 'There is two of  you... One of my favorite buildings nearby. Looks like the flood has been cleaned up or you find a nice angle. Well done!', '2014-06-30 02:00:45.000000', NULL, 1),
(7234580, 1120375, 28742, '<td valign="top">Nicely done!</td>', 'Nicely done!', '2014-06-30 02:42:37.000000', NULL, 1),
(7234657, 1120400, 18505, '<td valign="top">Commenting only on this one.... this is lovely.  You have creatively captured a beautifully serene environment.</td>', 'Commenting only on this one.... this is lovely.  You have creatively captured a beautifully serene environment.', '2014-06-30 10:43:13.000000', NULL, 1),
(7234659, 1120313, 18505, '<td valign="top">Commenting only....  Beautifully done.  I love the contrasts between light and dark and warm and cool.  What an interesting landmark!  I''m looking forward to reading the history.</td>', 'Commenting only....  Beautifully done.  I love the contrasts between light and dark and warm and cool.  What an interesting landmark!  I''m looking forward to reading the history.', '2014-06-30 10:46:59.000000', NULL, 1),
(7234660, 1120201, 18505, '<td valign="top">Commenting only....  Beautifully done.  Gorgeous colors, lovely composition...  I bet we see this on the front page.</td>', 'Commenting only....  Beautifully done.  Gorgeous colors, lovely composition...  I bet we see this on the front page.', '2014-06-30 10:50:50.000000', NULL, 1),
(7234688, 1120482, 16046, '<td valign="top">Best in show award, congrats</td>', 'Best in show award, congrats', '2014-06-30 12:19:21.000000', NULL, 1),
(7234722, 1120387, 141826, '<td valign="top">How beautiful!!!!!!!! 10+</td>', 'How beautiful!!!!!!!! 10+', '2014-06-30 14:56:46.000000', NULL, 1),
(7234737, 1119404, 67258, '<td valign="top">this does look interesting - so strange to see this splendid building in such apparent isolation.  I look forward to reading more about it.</td>', 'this does look interesting - so strange to see this splendid building in such apparent isolation.  I look forward to reading more about it.', '2014-06-30 16:09:11.000000', NULL, 1),
(7234739, 1119771, 67258, '<td valign="top">Oh, WOW!  Seriously, WOW!  Guess what, I am pretty impressed.  I am only a slack handful of photos into voting, but I cannot imagine any beating this...</td>', 'Oh, WOW!  Seriously, WOW!  Guess what, I am pretty impressed.  I am only a slack handful of photos into voting, but I cannot imagine any beating this...', '2014-06-30 16:12:19.000000', NULL, 1),
(7234740, 1120053, 67258, '<td valign="top">Super composition  that entirely suits the modernity of this historical landmark.  Good control of exposure, too.</td>', 'Super composition  that entirely suits the modernity of this historical landmark.  Good control of exposure, too.', '2014-06-30 16:13:25.000000', NULL, 1),
(7234742, 1120529, 67258, '<td valign="top">Looks like the side light was a little harsh, and working against you. Earlier (or later ) in the day and a little more light on the front of the building may have helped your exposure.  Alternatively, a more angled shot, taking in some of the side of the building with the light on it.</td>', 'Looks like the side light was a little harsh, and working against you. Earlier (or later ) in the day and a little more light on the front of the building may have helped your exposure.  Alternatively, a more angled shot, taking in some of the side of the building with the light on it.', '2014-06-30 16:15:43.000000', NULL, 1),
(7234743, 1120494, 67258, '<td valign="top">Very, very cool, and a composition and processing to suit the architecture.</td>', 'Very, very cool, and a composition and processing to suit the architecture.', '2014-06-30 16:16:29.000000', NULL, 1),
(7234752, 1120472, 18505, '<td valign="top">What an amazing find, beautifully and creatively presented.  I can''t vote on this, of course, but it would receive high marks indeed if I could.  I absolutely love the texture on the stones.  I know the sign says 1831, but it looks like it could easily be a thousand years older than that.  Awesome!</td>', 'What an amazing find, beautifully and creatively presented.  I can''t vote on this, of course, but it would receive high marks indeed if I could.  I absolutely love the texture on the stones.  I know the sign says 1831, but it looks like it could easily be a thousand years older than that.  Awesome!', '2014-06-30 16:37:09.000000', NULL, 1),
(7234754, 1120311, 18505, '<td valign="top">What a gorgeous landmark.  I love the reflection of the clouds in the the doorway and how the colors blend from gray in front to gold the higher up you go.  This is beautiful!!</td>', 'What a gorgeous landmark.  I love the reflection of the clouds in the the doorway and how the colors blend from gray in front to gold the higher up you go.  This is beautiful!!', '2014-06-30 16:40:11.000000', NULL, 1),
(7234799, 1119729, 60173, '<td valign="top">I love how you''ve processed this. Especially after seeing the title, the image is very creepy. It seems like there''s a slight, intentional blur covering the whole image, except the door. This kind of sucks me into the door. It''s as if there''s a witch inside and she''s put a spell on me!</td>', 'I love how you''ve processed this. Especially after seeing the title, the image is very creepy. It seems like there''s a slight, intentional blur covering the whole image, except the door. This kind of sucks me into the door. It''s as if there''s a witch inside and she''s put a spell on me!', '2014-06-30 20:00:39.000000', NULL, 1),
(7234800, 1119697, 60173, '<td valign="top">The HDR-like processing you did has a nice effect on most of the image, but not so much once the roof hits the sky. There''s lots of noticeable haloing. I think you could have backed off a little on the processing, kept the colors, and still presented a striking image. It does look as though you did try to use some restraint with the processing, but I think a wee more restraint is warranted.</td>', 'The HDR-like processing you did has a nice effect on most of the image, but not so much once the roof hits the sky. There''s lots of noticeable haloing. I think you could have backed off a little on the processing, kept the colors, and still presented a striking image. It does look as though you did try to use some restraint with the processing, but I think a wee more restraint is warranted.', '2014-06-30 20:04:18.000000', NULL, 1),
(7234802, 1120497, 60173, '<td valign="top">I think 3 steps to the left would have helped this image immensely. I feel that buildings like this were meant to be powerful and strong. Having the home totally square and center would have helped to convey these feelings.</td>', 'I think 3 steps to the left would have helped this image immensely. I feel that buildings like this were meant to be powerful and strong. Having the home totally square and center would have helped to convey these feelings.', '2014-06-30 20:06:23.000000', NULL, 1),
(7234803, 1120482, 60173, '<td valign="top">There''s some strong haloing around the tower (perhaps over-sharpened?), but otherwise a very nice photo.</td>', 'There''s some strong haloing around the tower (perhaps over-sharpened?), but otherwise a very nice photo.', '2014-06-30 20:08:34.000000', NULL, 1),
(7234805, 1120392, 60173, '<td valign="top">Too much bush and not enough house, but then again, maybe that''s what you were going for. If that''s what you''re going for, I would have liked to see a little more variation in tones in the bushy area. I think I see some sort of trumpet flower, but it''s hard to pick anything out. Everything''s just kind of flat.</td>', 'Too much bush and not enough house, but then again, maybe that''s what you were going for. If that''s what you''re going for, I would have liked to see a little more variation in tones in the bushy area. I think I see some sort of trumpet flower, but it''s hard to pick anything out. Everything''s just kind of flat.', '2014-06-30 20:10:36.000000', NULL, 1),
(7234808, 1120473, 60173, '<td valign="top">I would imagine this is a very grand and tall pipe organ of some sort. What''s interesting is that your chosen perspective has actually kind of made it look short and squashed.</td>', 'I would imagine this is a very grand and tall pipe organ of some sort. What''s interesting is that your chosen perspective has actually kind of made it look short and squashed.', '2014-06-30 20:12:52.000000', NULL, 1),
(7234809, 1119771, 60173, '<td valign="top">Having no idea what a "shot tower" was, I looked it up. Way cool! <br/> <br/>Also looking through the images on the Web, yours is the best out there. It''s also my favorite for the challenge. Judging by other photos of this structure, a good angle of shot is something not easily achieved. Many of the other photos out there also had a lot of distracting shadows on the main structure, whereas you seem to have none. Overcast perhaps? I also like how you used the square edge of the tower as a leading line. Overall, there''s a lovely luminance about the scene.</td>', 'Having no idea what a "shot tower" was, I looked it up. Way cool!  Also looking through the images on the Web, yours is the best out there. It''s also my favorite for the challenge. Judging by other photos of this structure, a good angle of shot is something not easily achieved. Many of the other photos out there also had a lot of distracting shadows on the main structure, whereas you seem to have none. Overcast perhaps? I also like how you used the square edge of the tower as a leading line. Overall, there''s a lovely luminance about the scene.', '2014-06-30 20:18:04.000000', NULL, 1),
(7234843, 1120548, 30861, '<td valign="top">I know this one well. Bodega, CA. Somewhere I have a wonderful, old print of it from my early days. I spent a couple weeks every summer in Bodega. Beautiful Zone System rendering here.</td>', 'I know this one well. Bodega, CA. Somewhere I have a wonderful, old print of it from my early days. I spent a couple weeks every summer in Bodega. Beautiful Zone System rendering here.', '2014-06-30 22:32:38.000000', NULL, 1),
(7234880, 1120094, 30982, '<td valign="top">I know right where this is!  You''re in Wiesbaden!  I''m envious.  I miss it.</td>', 'I know right where this is!  You''re in Wiesbaden!  I''m envious.  I miss it.', '2014-07-01 02:47:36.000000', NULL, 1),
(7234881, 1120438, 67258, '<td valign="top">Super composition.  The spires and dome just peeking over the building add a sense of place.</td>', 'Super composition.  The spires and dome just peeking over the building add a sense of place.', '2014-07-01 02:56:23.000000', NULL, 1),
(7234883, 1119691, 67258, '<td valign="top">Fascinating.  Well exposed and composed, but lacking somewhat in sharpness.</td>', 'Fascinating.  Well exposed and composed, but lacking somewhat in sharpness.', '2014-07-01 02:57:12.000000', NULL, 1),
(7234943, 1120387, 174999, '<td valign="top">Very interesting! Can''t wait to see the link about this! 10! Love the reflections and the sunset on this building</td>', 'Very interesting! Can''t wait to see the link about this! 10! Love the reflections and the sunset on this building', '2014-07-01 08:16:56.000000', NULL, 1),
(7234944, 1119697, 174999, '<td valign="top">This is very, very cool!!! never knew a lighthouse looked like this before..<br/> <br/>Don''t care for the lamp post in the middle, kinda distracting to me though, still a high score though.. very well processed!</td>', 'This is very, very cool!!! never knew a lighthouse looked like this before.. Don''t care for the lamp post in the middle, kinda distracting to me though, still a high score though.. very well processed!', '2014-07-01 08:18:10.000000', NULL, 1),
(7234946, 1120529, 175946, '<td valign="top">Nice subject and like the detail above the brick. There is a halo along the  roof line, the electrical wires in the sky on the left are a distraction and the main subject, the front of the building is a bit dark. It might have been better to shoot this at some other time of the day. Could not help but wonder what might  have been possible with this building at night using flashlights to do light painting.</td>', 'Nice subject and like the detail above the brick. There is a halo along the  roof line, the electrical wires in the sky on the left are a distraction and the main subject, the front of the building is a bit dark. It might have been better to shoot this at some other time of the day. Could not help but wonder what might  have been possible with this building at night using flashlights to do light painting.', '2014-07-01 09:00:03.000000', NULL, 1),
(7234947, 1120286, 175946, '<td valign="top">focus seems just a little soft, might have cloned out that wire on the left</td>', 'focus seems just a little soft, might have cloned out that wire on the left', '2014-07-01 09:01:18.000000', NULL, 1),
(7234948, 1120399, 175946, '<td valign="top">focus do not look tack sharp, great subject</td>', 'focus do not look tack sharp, great subject', '2014-07-01 09:03:09.000000', NULL, 1),
(7234950, 1120430, 175946, '<td valign="top">the missing door is a distraction for me in the overall image, symmetry is not there and you might have cropped of the left so it matched the right exactly</td>', 'the missing door is a distraction for me in the overall image, symmetry is not there and you might have cropped of the left so it matched the right exactly', '2014-07-01 09:06:59.000000', NULL, 1),
(7234951, 1120485, 175946, '<td valign="top">great symmetry and subject, but the overexposed sunlight on the floor took away. Would be  great subject to try HDR maybe.</td>', 'great symmetry and subject, but the overexposed sunlight on the floor took away. Would be  great subject to try HDR maybe.', '2014-07-01 09:08:25.000000', NULL, 1),
