(7235909, 1120311, 175946, '<td valign="top">consider sizing to 600 max on vertical side so that it all fits on the screen without scrolling - a bit of a halo effect on the edge of the roof on the right side - maybe ease back on the process</td>', 'consider sizing to 600 max on vertical side so that it all fits on the screen without scrolling - a bit of a halo effect on the edge of the roof on the right side - maybe ease back on the process', '2014-07-02 22:55:01.000000', NULL, 1),
