(7236656, 1120097, 70270, '<td valign="top">Ahh, the SB Mission.  Takes me back.  Good time to shoot it, and the chalk art makes it more than just a pretty picture.  well done!</td>', 'Ahh, the SB Mission.  Takes me back.  Good time to shoot it, and the chalk art makes it more than just a pretty picture.  well done!', '2014-07-04 14:57:10.000000', NULL, 1),
(7236657, 1120504, 70270, '<td valign="top">I like this a lot.  At first glance its just a postcard shot, but the longer you look the more there is to see.  The processing really brings out the detail here.</td>', 'I like this a lot.  At first glance its just a postcard shot, but the longer you look the more there is to see.  The processing really brings out the detail here.', '2014-07-04 14:57:58.000000', NULL, 1),
