(7236661, 1120438, 70270, '<td valign="top">cool old building.  like the perspective and processing.  The fall off in the lines to the right is just a bit too pronounced, but still a really nice image.</td>', 'cool old building.  like the perspective and processing.  The fall off in the lines to the right is just a bit too pronounced, but still a really nice image.', '2014-07-04 15:02:51.000000', NULL, 1),
(7236663, 1119697, 70270, '<td valign="top">nice picture of a nice building and nicely processed.  A wider shot to show a bit more of the context where this building sits would make it really nice.</td>', 'nice picture of a nice building and nicely processed.  A wider shot to show a bit more of the context where this building sits would make it really nice.', '2014-07-04 15:04:41.000000', NULL, 1),
