(7236784, 1120339, 58634, '<td valign="top">Great perspective. It really make this image pop. I just wish the slight piece of the ceiling wouldn''t have gotten cut off</td>', 'Great perspective. It really make this image pop. I just wish the slight piece of the ceiling wouldn''t have gotten cut off', '2014-07-04 19:37:17.000000', NULL, 1),
(7236785, 1120163, 58634, '<td valign="top">I like this image because it actually have an old time feeling for it which fits it really well. I also like the perspective that you''ve chosen.</td>', 'I like this image because it actually have an old time feeling for it which fits it really well. I also like the perspective that you''ve chosen.', '2014-07-04 19:38:00.000000', NULL, 1),
(7236786, 1120200, 58634, '<td valign="top">It flows nicely as far as the geometry of it goes. However, personally, I would''ve chosen NOT to crop off the flags at the bottom</td>', 'It flows nicely as far as the geometry of it goes. However, personally, I would''ve chosen NOT to crop off the flags at the bottom', '2014-07-04 19:38:56.000000', NULL, 1),
(7236787, 1120468, 58634, '<td valign="top">Beautiful image but why is it so noisy?</td>', 'Beautiful image but why is it so noisy?', '2014-07-04 19:39:13.000000', NULL, 1),
(7236788, 1120547, 58634, '<td valign="top">Not sharp enough but great perspective and nice colors throughout.</td>', 'Not sharp enough but great perspective and nice colors throughout.', '2014-07-04 19:39:35.000000', NULL, 1),
(7236789, 1120008, 58634, '<td valign="top">Looks like an awesome street shot. Great use of B&amp;W too; it is perfectly balanced.</td>', 'Looks like an awesome street shot. Great use of B&W too; it is perfectly balanced.', '2014-07-04 19:40:04.000000', NULL, 1),
(7236790, 1120286, 58634, '<td valign="top">I like the war light here.</td>', 'I like the war light here.', '2014-07-04 19:40:33.000000', NULL, 1),
(7236791, 1120160, 58634, '<td valign="top">IMHO, I don''t find much interesting about this image. If it wasn''t for the title, I''d just think it''s a wall of rocks or dirt..  And although I like the geometry in the curve between it and the sky, I can''t help but feel as if maybe this location could''ve been photographed in a way that would really make it noticeable.</td>', 'IMHO, I don''t find much interesting about this image. If it wasn''t for the title, I''d just think it''s a wall of rocks or dirt..  And although I like the geometry in the curve between it and the sky, I can''t help but feel as if maybe this location could''ve been photographed in a way that would really make it noticeable.', '2014-07-04 19:43:02.000000', NULL, 1),
(7236792, 1120399, 58634, '<td valign="top">Nice sepia tones. A bit of an unusual angle though.</td>', 'Nice sepia tones. A bit of an unusual angle though.', '2014-07-04 19:43:36.000000', NULL, 1),
(7236793, 1120529, 58634, '<td valign="top">Wow, schools have certainly come a long way since then! Interesting find.</td>', 'Wow, schools have certainly come a long way since then! Interesting find.', '2014-07-04 19:45:13.000000', NULL, 1),
(7236794, 1120348, 58634, '<td valign="top">I really like the fact that you made the image look so vintage. It''s very fitting both with the challenge, as well as the building itself.</td>', 'I really like the fact that you made the image look so vintage. It''s very fitting both with the challenge, as well as the building itself.', '2014-07-04 19:45:49.000000', NULL, 1),
(7236795, 1120375, 58634, '<td valign="top">Now THIS is something unlike anything I''ve ever seen before.</td>', 'Now THIS is something unlike anything I''ve ever seen before.', '2014-07-04 19:47:52.000000', NULL, 1),
(7236799, 1120547, 176157, '<td valign="top">Beautiful and scenic photo.</td>', 'Beautiful and scenic photo.', '2014-07-04 19:50:53.000000', NULL, 1),
(7236803, 1120472, 58634, '<td valign="top">6</td>', '6', '2014-07-04 20:00:24.000000', NULL, 1),
(7236804, 1120384, 58634, '<td valign="top">I really like how warm the colors look.</td>', 'I really like how warm the colors look.', '2014-07-04 20:00:46.000000', NULL, 1),
(7236805, 1120485, 58634, '<td valign="top">Really gorgeous lighting here.</td>', 'Really gorgeous lighting here.', '2014-07-04 20:01:13.000000', NULL, 1),
(7236807, 1120196, 176157, '<td valign="top">It looks so inviting! Very nice.</td>', 'It looks so inviting! Very nice.', '2014-07-04 20:04:27.000000', NULL, 1),
(7236809, 1120281, 176157, '<td valign="top">I like what you did here.</td>', 'I like what you did here.', '2014-07-04 20:07:27.000000', NULL, 1),
(7236810, 1120438, 58634, '<td valign="top">Exquisite location. I''m curious to find out where this image was taken. I am from Ecuador and a lot of the architecture in the country''s capital (Quito) is similar to this, especially with the garden in the middle of the building so I''m immediately drawn to the beauty of it. <br/> <br/>You''ve managed to really make every corner of this building shine and no areas were overblown with highlights or viceversa so really nice job on this.</td>', 'Exquisite location. I''m curious to find out where this image was taken. I am from Ecuador and a lot of the architecture in the country''s capital (Quito) is similar to this, especially with the garden in the middle of the building so I''m immediately drawn to the beauty of it.  You''ve managed to really make every corner of this building shine and no areas were overblown with highlights or viceversa so really nice job on this.', '2014-07-04 20:08:11.000000', NULL, 1),
(7236811, 1120161, 58634, '<td valign="top">Very quaint and cute location. I like your use of a slight vignette too as it fits this quite nicely.</td>', 'Very quaint and cute location. I like your use of a slight vignette too as it fits this quite nicely.', '2014-07-04 20:09:14.000000', NULL, 1),
(7236812, 1119733, 176157, '<td valign="top">I like it</td>', 'I like it', '2014-07-04 20:11:24.000000', NULL, 1),
(7236813, 1120525, 58634, '<td valign="top">Scrolling through the thumbnails, this image stood out to me immediately and with enough power that it made me want to view it in full size which is unusual because I don''t usually do that, but rather vote in order.<br/> <br/>With that said, this is really beautiful. The tone throughout the image is expertly manipulated to make it stand out just enough from the rest. The level of sharpness is also top notch and I really love how the lights and shadows here really make everything stand out so beautifully. Finally, the clouds look so great here, they bring a certain power to the  building that I don''t quite know how else to describe. <br/> <br/>All in all, excellent image!</td>', 'Scrolling through the thumbnails, this image stood out to me immediately and with enough power that it made me want to view it in full size which is unusual because I don''t usually do that, but rather vote in order. With that said, this is really beautiful. The tone throughout the image is expertly manipulated to make it stand out just enough from the rest. The level of sharpness is also top notch and I really love how the lights and shadows here really make everything stand out so beautifully. Finally, the clouds look so great here, they bring a certain power to the  building that I don''t quite know how else to describe.  All in all, excellent image!', '2014-07-04 20:14:06.000000', NULL, 1),
(7236814, 1120200, 176157, '<td valign="top">Something draws me to this.  Maybe all the geometry and symmetry.  Its neat.</td>', 'Something draws me to this.  Maybe all the geometry and symmetry.  Its neat.', '2014-07-04 20:15:30.000000', NULL, 1),
(7236815, 1120549, 176157, '<td valign="top">Wow!</td>', 'Wow!', '2014-07-04 20:16:51.000000', NULL, 1),
(7236826, 1119413, 176157, '<td valign="top">Something about old railroad stations... Very nice</td>', 'Something about old railroad stations... Very nice', '2014-07-04 20:27:13.000000', NULL, 1),
(7236835, 1119771, 176157, '<td valign="top">That is so cool.</td>', 'That is so cool.', '2014-07-04 21:03:37.000000', NULL, 1),
(7236836, 1120392, 176157, '<td valign="top">I like the old photograph vintage look.</td>', 'I like the old photograph vintage look.', '2014-07-04 21:05:57.000000', NULL, 1),
(7236837, 1120438, 176157, '<td valign="top">Nicely composed. The red adds a lot to the overall shot - I think.</td>', 'Nicely composed. The red adds a lot to the overall shot - I think.', '2014-07-04 21:08:37.000000', NULL, 1),
(7236839, 1120279, 176157, '<td valign="top">BAM! I really enjoy this photo. It''s stunning. I like all the detail and depth of field and color.  And, after researching this, I see it is close to where I''ll be relocating soon.  So'' I''ll definately have to check it out.  Thanks for submitting this photo.  Its awesome.</td>', 'BAM! I really enjoy this photo. It''s stunning. I like all the detail and depth of field and color.  And, after researching this, I see it is close to where I''ll be relocating soon.  So'' I''ll definately have to check it out.  Thanks for submitting this photo.  Its awesome.', '2014-07-04 21:13:18.000000', NULL, 1),
(7236841, 1120478, 176157, '<td valign="top">Overall, great photo.  What caught my attention:  the real shutters on the windows.  I''m nutty that way. I like the overall composition and how you got the sun to cooperate.</td>', 'Overall, great photo.  What caught my attention:  the real shutters on the windows.  I''m nutty that way. I like the overall composition and how you got the sun to cooperate.', '2014-07-04 21:14:15.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7236842, 1119696, 176157, '<td valign="top">I Google''d "Thompson Hosue" to see what it is.  Your photo looks a lot nicer than the one on the one web site I was directed to. Your colors are very pleasant.</td>', 'I Google''d "Thompson Hosue" to see what it is.  Your photo looks a lot nicer than the one on the one web site I was directed to. Your colors are very pleasant.', '2014-07-04 21:14:31.000000', NULL, 1),
(7236843, 1120488, 176157, '<td valign="top">Now, that''s a landmark.  Wierd seeing modern cars at a drive in.</td>', 'Now, that''s a landmark.  Wierd seeing modern cars at a drive in.', '2014-07-04 21:14:59.000000', NULL, 1),
(7236844, 1120312, 176157, '<td valign="top">Looks like a quiet place to go relax.</td>', 'Looks like a quiet place to go relax.', '2014-07-04 21:15:50.000000', NULL, 1),
