(7239522, 1120057, 43463, '<td valign="top">Congrats on your 4th place finish! Love the bold reds of the lighthouse and the Canadian Flag. The red and white color scheme plays out very well thoughout the composition - from the lighthouse to the flag and then to the crip, cold white of the glacier in the ocean. Nicely seen and captured.</td>', 'Congrats on your 4th place finish! Love the bold reds of the lighthouse and the Canadian Flag. The red and white color scheme plays out very well thoughout the composition - from the lighthouse to the flag and then to the crip, cold white of the glacier in the ocean. Nicely seen and captured.', '2014-07-10 12:27:13.000000', NULL, 0),
(7240236, 1120384, 50641, '<td valign="top">Agree with Brennan, this should have done better.</td>', 'Agree with Brennan, this should have done better.', '2014-07-12 11:29:06.000000', NULL, 0),
(7248493, 1120438, 115814, '<td valign="top">You did a great job of organizing the scene. You''ve centered the main column, but the slight variance of angle for the left and right hallways combine with the framed placement of the cathedral spires under the left arch to create a combined centered/non-centered balance that works well.</td>', 'You did a great job of organizing the scene. You''ve centered the main column, but the slight variance of angle for the left and right hallways combine with the framed placement of the cathedral spires under the left arch to create a combined centered/non-centered balance that works well.', '2014-08-07 17:22:16.000000', NULL, 0),
(7301316, 1120175, 9581, '<td valign="top">I just love clocks and buildings in the cities.. This is very nice framing and the colors are excellent.</td>', 'I just love clocks and buildings in the cities.. This is very nice framing and the colors are excellent.', '2015-01-12 07:36:07.000000', NULL, 0),
